@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 text-light me-2" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in Services.WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge" title="Low-stock items at @WarehouseState.CurrentWarehouseId">
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

